insert into public.privileges (id, code, title, description, category, basis) values
  ('833b6697-aa24-5921-954f-2dcc05f40746', 'dev_prv_embark', 'Priority, unhurried embarkation', 'A personal arrival window and escort straight to your Grand Suite. No queue at the gangway.', 'arrival', 'bonvoy-tier'),
  ('8b85c8e4-1d87-5750-a615-37c86c88cb97', 'dev_prv_amenity', 'Your welcome amenity', 'Brunello di Montalcino and chilled sparkling water, waiting in your suite with a note from Elena.', 'suite', 'bonvoy-tier'),
  ('11dcb7bc-e28e-5b32-9cd0-b3f3f3aa9438', 'dev_prv_chefs', 'An evening at the Chef''s Counter', 'Reserved seats at the eight-seat counter on the sea day, with the head sommelier pairing red wines.', 'dining', 'voyage-tenure'),
  ('5a9fbb42-393e-5aa9-8338-5a762cf8469b', 'dev_prv_spa', 'Preferred spa scheduling', 'First choice of morning treatment times, 72 hours before they open to all guests.', 'wellness', 'bonvoy-tier'),
  ('168a557e-5a3a-53e1-80f7-ed2dc4481172', 'dev_prv_window', 'Your window table, held', 'A window table for two is held for you each evening in Mediterraneo, unless you choose elsewhere.', 'dining', 'voyage-tenure'),
  ('85779ad0-7038-543d-a6bd-995cc2682d5f', 'dev_prv_late', 'Late disembarkation', 'Remain in your Grand Suite until your car to Fiumicino, with breakfast on your terrace.', 'suite', 'suite-category'),
  ('a69b8f7c-cce8-58ea-a159-fec6705a3fb5', 'dev_prv_occasion', 'Your anniversary, quietly arranged', 'Elena knows about your 20th anniversary in Monte Carlo and will arrange as much, or as little, as you wish.', 'recognition', 'occasion')
