  ('e0f5c0ad-d2b8-5546-96d3-01043b0c20c7', '9c79f37b-eb46-5b3e-8409-334434c315e1', 4, '2027-05-18', 'tender', 'Saint-Tropez', 'France', 'Europe/Paris', '2027-05-18T08:00:00+02:00', '2027-05-18T23:00:00+02:00', '2027-05-18T22:30:00+02:00', 'A classic yacht under sail in the bay, and the marina platform open in the afternoon.', point(6.6406, 43.2727), '{"alt":"Classic sailing yachts off Saint-Tropez","tone":["#1F3A4D","#7F9C96"]}'::jsonb),
  ('fb0f36b9-b77b-55d4-bae0-2d3f2779b6f4', '9c79f37b-eb46-5b3e-8409-334434c315e1', 5, '2027-05-19', 'overnight', 'Monte Carlo', 'Monaco', 'Europe/Monaco', '2027-05-19T08:00:00+02:00', null, null, 'Overnight in Port Hercule. The Oceanographic Museum before opening and the Principality after dark.', point(7.4206, 43.7347), '{"alt":"Port Hercule, Monaco","tone":["#0E1A2B","#3A5068"]}'::jsonb),
