insert into public.guest_preferences (guest_id, preferred_destinations, dining, dietary, beverage, suite, activity_interests, excursions, spa, transportation, accessibility, communication, privacy, version) values
  ('541910dc-d171-542d-8575-3a8d893adf79', array['French Riviera', 'Italian Riviera', 'Balearic Islands', 'Adriatic', 'Greek Islands']::text[], '{"cuisines":["Mediterranean","Ligurian","Provençal","Catalan"],"tablePreference":"window","preferredTime":"20:30","preferredSeating":"Window table for two, facing the sea","notes":"Prefers dinner from 20:30. Enjoys a word with the chef; dislikes long tasting menus on port days."}'::jsonb, '{"restrictions":[],"allergies":[]}'::jsonb, '{"wine":["Red wine — Barolo, Brunello di Montalcino, Saint-Émilion","Champagne for celebrations"],"spirits":["Aged rum (neat)"],"nonAlcoholic":["Sparkling water — San Pellegrino, no ice, with lemon","Espresso after dinner"],"welcomeAmenity":"A bottle of Brunello di Montalcino, decanted on request, with chilled sparkling water"}'::jsonb, '{"pillow":"Feather-free (synthetic down alternative) — all pillows and duvet","bedConfiguration":"king","temperatureCelsius":21,"turndown":"Blinds half-closed to keep the sea view; sparkling water on both nightstands","minibar":["Sparkling water (case)","Dark chocolate","No sugary soft drinks"],"newspapers":["The Wall Street Journal","Financial Times (digital)"]}'::jsonb, array['Fine dining', 'Wine', 'Private cultural experiences', 'Spa', 'Yachting & sailing']::text[], '{"style":"private","pace":"leisurely","maxDurationMinutes":300,"notes":"Private guide and vehicle always. Prefers early access before crowds; avoids large-group coaches."}'::jsonb, '{"favouriteTreatments":["Deep-tissue massage","Thalassotherapy","Couples ritual (with Camille)"],"pressure":"firm","preferredTime":"morning","notes":"Male or female therapist, no preference. Unscented oil."}'::jsonb, '{"arrivals":"private-car","cabin":"business","helicopterWelcome":true,"notes":"Prefers a sedan to an SUV. No music in the car, please."}'::jsonb, '{"mobility":"none","tenderAssistance":false,"hearingSupport":false,"visualSupport":false,"shareWithCrew":true}'::jsonb, '{"channels":{"push":true,"email":true,"sms":true,"whatsapp":false},"quietHours":{"start":"23:00","end":"07:00"},"language":"en-US","marketingConsent":true}'::jsonb, '{"personalisedRecommendations":true,"shareOccasionsWithCrew":true,"shareDietaryWithPartners":true,"analytics":false}'::jsonb, 1)
