  ('996a46b4-75c4-5928-a366-17cfcffde74d', '9c79f37b-eb46-5b3e-8409-334434c315e1', null, 'dining', 'Mediterraneo', 'The coast’s kitchens, by the window', 'Catalan, Provençal and Ligurian dishes cooked from the morning’s market, in a room lined with sea-facing windows.', null, null, null, true, false, null, array['mediterranean', 'window', 'fine-dining']::text[], '{"alt":"Window table at Mediterraneo at dusk","tone":["#1F3A4D","#7F9C96"]}'::jsonb, 'shared', array['Window table held each evening', 'Wine by the glass from the sommelier’s list']::text[], null, 'available', null, 0),
  ('ee32c691-c22c-5f61-9750-24b41396cbb0', '9c79f37b-eb46-5b3e-8409-334434c315e1', null, 'dining', 'Lumière', 'Contemporary French, by candlelight', 'Twelve tables and a cellar of grower Champagnes and Right Bank Bordeaux.', null, null, null, true, false, null, array['french', 'fine-dining', 'window']::text[], '{"alt":"Candlelit table at Lumière","tone":["#0B111C","#1E2530"]}'::jsonb, 'shared', array['Twelve-table dining room', 'Champagne and Bordeaux cellar']::text[], null, 'available', null, 1),
  ('9dddc706-ef99-5f60-9beb-d0fc2acb49ac', '9c79f37b-eb46-5b3e-8409-334434c315e1', null, 'dining', 'Il Giardino', 'Riviera Italian on the open terrace', 'Trofie al pesto, branzino al sale and a glass-screened terrace on Deck 9.', null, null, null, true, false, null, array['italian', 'mediterranean', 'al-fresco']::text[], '{"alt":"Terrace dining at sunset","tone":["#6E3B2A","#C99A7A"]}'::jsonb, 'shared', array['Glass-screened terrace table']::text[], null, 'available', null, 2),
  ('f3adb606-6c02-5ff8-bfe0-0003ac35dec7', '9c79f37b-eb46-5b3e-8409-334434c315e1', null, 'dining', 'The Chef''s Counter', 'Eight seats, one menu, the chef in front of you', 'A seven-course Mediterranean tasting with a red-wine pairing led by the head sommelier.', 165, 34000, 'EUR', false, true, 8, array['tasting', 'chef', 'wine', 'fine-dining']::text[], '{"alt":"Chef plating at the counter","tone":["#5A4A32","#E8DCC4"]}'::jsonb, 'small-group', array['Seven courses', 'Red-wine pairing by the head sommelier', 'Conversation with the chef']::text[], null, 'limited', 'Two seats left on 19 May', 3),
  ('0d1b7bd7-4511-5882-b65d-6cc17a9b6738', '9c79f37b-eb46-5b3e-8409-334434c315e1', null, 'dining', 'Dinner on a Private Terrace', 'A table for two, set above the harbour', 'A menu composed with the chef, a sommelier for the evening, and Monaco’s lights all around.', 180, 120000, 'EUR', false, true, 2, array['private', 'occasion', 'fine-dining', 'wine']::text[], '{"alt":"Candlelit table on a terrace above a harbour","tone":["#3B1420","#8C4A5A"]}'::jsonb, 'private', array['Menu composed with the chef', 'Sommelier for the evening', 'Flowers and candlelight']::text[], null, 'limited', 'One private terrace, by arrangement', 4),
  ('e6b8b406-9306-50bf-8fa7-33cc72862d91', '9c79f37b-eb46-5b3e-8409-334434c315e1', null, 'wine', 'Barolo & Saint-Émilion, Side by Side', 'A sea-day masterclass in the wine library', 'Six reds, two great regions, one table of twelve, led by the head sommelier.', 90, 16000, 'EUR', false, true, 12, array['wine', 'red-wine']::text[], '{"alt":"Glasses of red wine in a wine library","tone":["#3B1420","#8C4A5A"]}'::jsonb, 'small-group', array['Six reds, poured side by side', 'Tasting notes to take home']::text[], null, 'limited', 'Four places left', 5),
  ('88210ade-7954-5da4-abb3-038f21136a43', '9c79f37b-eb46-5b3e-8409-334434c315e1', 'ed45ec45-807a-5037-980f-4a8d282876fa', 'wine', 'Binissalem Vineyards & Lunch in Deià', 'A family estate, a private guide, a clifftop table', 'Taste Mantonegro reds with the winemaker, then drive the Tramuntana to lunch above the sea in Deià.', 300, 145000, 'EUR', false, true, null, array['wine', 'red-wine', 'private', 'culinary']::text[], '{"alt":"Vineyards below the Tramuntana mountains","tone":["#3C4A35","#A7AE8C"]}'::jsonb, 'private', array['Private car and guide', 'Barrel tasting with the winemaker', 'Lunch in Deià']::text[], 'Palma de Mallorca', 'available', null, 6),
  ('43742171-21cd-500b-8454-8075bf695606', '9c79f37b-eb46-5b3e-8409-334434c315e1', null, 'spa', 'Deep-Tissue Recovery Massage', 'Ninety minutes, firm pressure, unscented oil', 'Focused work on back and shoulders after long-haul travel, followed by time in the relaxation room.', 90, 26000, 'EUR', false, true, null, array['spa', 'massage']::text[], '{"alt":"Spa treatment room with sea view","tone":["#5B5750","#CFC5B6"]}'::jsonb, 'private', array['90-minute treatment', 'Relaxation room afterwards']::text[], null, 'available', 'Morning times open to you 72 hours early', 7),
  ('f3752a7d-ddbf-5113-8f0b-0efd346e6d1b', '9c79f37b-eb46-5b3e-8409-334434c315e1', null, 'spa', 'Thalassotherapy Circuit', 'Warm seawater pool, sauna and cold deluge', 'A sixty-minute circuit with a private lounger reserved.', 60, null, null, true, false, null, array['spa', 'thalassotherapy']::text[], '{"alt":"Thalassotherapy pool","tone":["#1F3A4D","#7F9C96"]}'::jsonb, 'shared', array['Seawater pool, sauna and cold deluge', 'Reserved lounger']::text[], null, 'available', null, 8),
  ('2e55535c-661f-51f2-b136-164914832d11', '9c79f37b-eb46-5b3e-8409-334434c315e1', null, 'spa', 'Couples Terrace Ritual', 'Side by side, open to the sea', 'Two hours in the couples suite: sea-salt exfoliation, massage and Champagne on its private terrace.', 120, 68000, 'EUR', false, true, null, array['spa', 'couples', 'occasion']::text[], '{"alt":"Couples spa terrace","tone":["#5A4A32","#E8DCC4"]}'::jsonb, 'private', array['Couples suite with private terrace', 'Champagne']::text[], null, 'limited', 'The couples suite is free on three afternoons', 9),
  ('2c3abd6d-55c2-582a-b3df-66c9b308a8f0', '9c79f37b-eb46-5b3e-8409-334434c315e1', '9eba89e2-eff9-55bd-a86e-d8f172615e7c', 'culture', 'The Sagrada Família, Privately', 'An architect-guide and the towers, before embarkation', 'Your driver meets you at arrivals; luggage goes ahead to the yacht while you see Gaudí’s basilica with an architect.', 120, 85000, 'EUR', false, true, null, array['private', 'culture', 'architecture']::text[], '{"alt":"Sagrada Família interior light","tone":["#6E3B2A","#C99A7A"]}'::jsonb, 'private', array['Architect-guide', 'Tower access', 'Car waits throughout']::text[], 'Barcelona', 'available', null, 10),
  ('548ea9d4-aee8-5ee3-8ab7-a672d85acb7f', '9c79f37b-eb46-5b3e-8409-334434c315e1', 'e0f5c0ad-d2b8-5546-96d3-01043b0c20c7', 'private', 'Under Sail on a 1930s Classic Yacht', 'Take the helm in the Bay of Saint-Tropez', 'A restored gaff-rigged sloop, her skipper and a steward. Swim stop at Pampelonne and lunch aboard.', 210, 240000, 'EUR', false, true, 6, array['private', 'yachting', 'sailing']::text[], '{"alt":"Classic wooden yacht under full sail","tone":["#1F3A4D","#7F9C96"]}'::jsonb, 'private', array['Skipper and steward', 'Swim stop at Pampelonne', 'Lunch aboard']::text[], 'Saint-Tropez', 'available', null, 11),
  ('39a17caf-054f-5b67-9d98-6f926c4189cd', '9c79f37b-eb46-5b3e-8409-334434c315e1', 'fb0f36b9-b77b-55d4-bae0-2d3f2779b6f4', 'culture', 'The Oceanographic Museum Before Opening', 'The cliff-top museum, with a curator, before the doors open', 'A private hour among the aquariums and the collections of Prince Albert I’s oceanographic voyages, then coffee on the terrace.', 120, 78000, 'EUR', false, true, null, array['private', 'culture', 'early-access', 'yachting']::text[], '{"alt":"Museum façade on the cliff above the sea","tone":["#5B5750","#CFC5B6"]}'::jsonb, 'private', array['Curator-led visit before opening', 'Coffee on the terrace', 'Private car']::text[], 'Monte Carlo', 'available', null, 12),
  ('869c0cf1-890a-5058-b564-d83bd47f111b', '9c79f37b-eb46-5b3e-8409-334434c315e1', '1f76a5d3-0268-53d2-8031-e8ed5e09a0cd', 'culture', 'Villa Ephrussi de Rothschild, Quietly', 'Nine gardens on Cap Ferrat, with a curator', 'An early private visit to the villa and its gardens, then lunch in Beaulieu-sur-Mer.', 180, 96000, 'EUR', false, true, null, array['private', 'culture', 'gardens', 'occasion']::text[], '{"alt":"Formal gardens above the bay","tone":["#3C4A35","#A7AE8C"]}'::jsonb, 'private', array['Curator', 'Private car', 'Lunch in Beaulieu-sur-Mer']::text[], 'Monte Carlo', 'available', null, 13),
  ('c897e06a-51c1-5910-8f4b-6158de6c746e', '9c79f37b-eb46-5b3e-8409-334434c315e1', '688d8712-196c-575e-a09e-551c97dbd755', 'private', 'San Fruttuoso by Riva', 'A mahogany launch to the abbey reachable only by sea', 'Captain and steward, a swim in the cove, and lunch at the water’s edge.', 240, 280000, 'EUR', false, true, 4, array['private', 'yachting', 'boat']::text[], '{"alt":"Riva launch in a turquoise cove","tone":["#1F3A4D","#7F9C96"]}'::jsonb, 'private', array['Captain and steward', 'Swim in the cove', 'Lunch at the water’s edge']::text[], 'Portofino', 'limited', 'Two launches that morning and afternoon', 14),
  ('1977eed4-d1e4-540a-a588-11f0a5a17800', '9c79f37b-eb46-5b3e-8409-334434c315e1', 'ed45ec45-807a-5037-980f-4a8d282876fa', 'culture', 'La Seu with a Historian', 'Gothic stone and Gaudí’s canopy', 'A private hour in Palma’s cathedral, including the terraces when open.', 75, 42000, 'EUR', false, true, null, array['private', 'culture', 'architecture']::text[], '{"alt":"Palma cathedral rose window","tone":["#5B5750","#CFC5B6"]}'::jsonb, 'private', array['Historian-guide', 'Terraces when open']::text[], 'Palma de Mallorca', 'available', null, 15),
  ('675535bd-d2f3-5b1b-a6ca-4c42f916f33e', '9c79f37b-eb46-5b3e-8409-334434c315e1', '688d8712-196c-575e-a09e-551c97dbd755', 'excursion', 'The Lighthouse Path at Golden Hour', 'An easy walk to Punta Capo', 'Twenty minutes from the piazzetta, with a glass of Vermentino at the lighthouse.', 90, null, null, true, true, 10, array['walking', 'culture']::text[], '{"alt":"Portofino lighthouse at sunset","tone":["#6E3B2A","#C99A7A"]}'::jsonb, 'private-or-group', array['Guide', 'A glass of Vermentino at the lighthouse']::text[], 'Portofino', 'available', null, 16),
  ('29eab976-926f-5a6e-911d-7bdf857834ee', '9c79f37b-eb46-5b3e-8409-334434c315e1', null, 'wellness', 'Sunrise Yoga on the Bow', 'Forty-five minutes as the coast wakes', 'A gentle flow on the forward deck with the yacht’s wellness coach. Mats, towels and fresh juices provided.', 45, null, null, true, false, 12, array['wellness', 'yoga', 'morning']::text[], '{"alt":"Yoga mats on a yacht deck at sunrise","tone":["#5A4A32","#E8DCC4"]}'::jsonb, 'small-group', array['Mats and towels', 'Fresh juices afterwards']::text[], null, 'available', null, 17),
  ('a92d3ee5-2fe3-54fb-b32f-6b4127665851', '9c79f37b-eb46-5b3e-8409-334434c315e1', null, 'wellness', 'A Private Session with the Wellness Coach', 'Mobility, breathwork and stretching, after the flight', 'One-to-one in the fitness studio or on your terrace, shaped around long-haul recovery.', 60, 18000, 'EUR', false, true, null, array['wellness', 'private', 'recovery']::text[], '{"alt":"Fitness studio with sea view","tone":["#1F3A4D","#7F9C96"]}'::jsonb, 'private', array['One-to-one coaching', 'A recovery plan for the voyage']::text[], null, 'available', null, 18),
  ('6774c5dc-3d60-585f-b7c0-39be823683c6', '9c79f37b-eb46-5b3e-8409-334434c315e1', 'ed45ec45-807a-5037-980f-4a8d282876fa', 'wellness', 'Morning Walk in the Tramuntana', 'Olive terraces and dry-stone paths above Valldemossa', 'An easy two-hour walk with a mountain guide, ending with coffee in the village square.', 150, 52000, 'EUR', false, true, null, array['wellness', 'walking', 'private', 'nature']::text[], '{"alt":"Terraced olive groves in the Tramuntana","tone":["#3C4A35","#A7AE8C"]}'::jsonb, 'private', array['Private mountain guide', 'Private car', 'Coffee in Valldemossa']::text[], 'Palma de Mallorca', 'unavailable', 'Fully booked. Your concierge can ask the guides about another hour.', 19),
  ('19296172-e452-544b-bfb2-32dd547ae8b4', '9c79f37b-eb46-5b3e-8409-334434c315e1', null, 'private', 'A Visit to the Bridge', 'Navigation with the Officer of the Watch', 'By invitation, on the sea day: charts, systems and the view from the bridge wings.', 45, null, null, true, true, 4, array['yachting', 'private']::text[], '{"alt":"Bridge of a yacht at sea","tone":["#0E1A2B","#3A5068"]}'::jsonb, 'private', array['Officer of the Watch', 'Bridge wings']::text[], null, 'limited', 'By invitation, on the sea day', 20),
  ('3b29f72a-67ee-5555-9f39-805339c615ff', '9c79f37b-eb46-5b3e-8409-334434c315e1', 'e0f5c0ad-d2b8-5546-96d3-01043b0c20c7', 'marina', 'The Marina Platform', 'Swim, paddleboard and kayak from the aft of the yacht', 'Weather permitting, the marina opens at anchor in the bay from 14:30.', 150, null, null, true, false, null, array['swimming', 'watersports', 'boat']::text[], '{"alt":"Swimmers off the yacht’s marina platform","tone":["#1F3A4D","#7F9C96"]}'::jsonb, 'shared', array['Paddleboards, kayaks and snorkelling gear', 'Marina team in attendance']::text[], 'Saint-Tropez', 'available', 'Weather permitting', 21),
  ('4a24acbe-69f3-5cc6-b1d2-2d1a4f1d5302', '9c79f37b-eb46-5b3e-8409-334434c315e1', null, 'entertainment', 'Jazz in the Observation Lounge', 'A trio, an aged rum, and the wake behind you', 'Nightly from 21:30 on Deck 10.', null, null, null, true, false, null, array['music', 'evening']::text[], '{"alt":"Lounge at night","tone":["#0B111C","#1E2530"]}'::jsonb, 'shared', '{}'::text[], null, 'available', null, 22),
  ('3c371a83-5ab8-5f3b-8bb2-097c236aa5bc', '9c79f37b-eb46-5b3e-8409-334434c315e1', 'fb0f36b9-b77b-55d4-bae0-2d3f2779b6f4', 'shopping', 'Private Atelier Appointments', 'Fine watchmaking and jewellery, by appointment', 'Your concierge arranges private viewings on Avenue des Beaux-Arts.', 90, null, null, true, true, null, array['shopping', 'private', 'occasion']::text[], '{"alt":"Jewellery atelier","tone":["#5A4A32","#E8DCC4"]}'::jsonb, 'private', array['Private viewings arranged by your concierge']::text[], 'Monte Carlo', 'available', null, 23),
  ('bc4a45e2-86cc-5d7a-a31b-d562bfd29792', '9c79f37b-eb46-5b3e-8409-334434c315e1', '9eba89e2-eff9-55bd-a86e-d8f172615e7c', 'transfer', 'Private Arrival Transfer', 'El Prat → Sagrada Família → Port Vell', 'Met at arrivals by name; your car waits during your visit, and luggage goes directly to your suite.', 210, null, null, true, true, null, array['transfer']::text[], '{"alt":"Chauffeured car","tone":["#0B111C","#1E2530"]}'::jsonb, 'private', array['Meet and greet at arrivals', 'Luggage sent ahead to your suite']::text[], 'Barcelona', 'available', null, 24),
  ('48f877b6-d8ca-56c7-9dae-ee0471b3f710', '9c79f37b-eb46-5b3e-8409-334434c315e1', '43b1a18e-fbae-5879-9e55-f27f3de1d463', 'transfer', 'Private Departure Transfer', 'Civitavecchia → Fiumicino', 'From the gangway to your terminal, luggage handled throughout.', 60, null, null, true, true, null, array['transfer']::text[], '{"alt":"Car on a coastal road","tone":["#3C4A35","#A7AE8C"]}'::jsonb, 'private', array['Luggage handled from suite to terminal']::text[], 'Rome', 'available', null, 25),
  ('721c40dd-4daf-5bd9-8c65-19aaccf72fed', '9c79f37b-eb46-5b3e-8409-334434c315e1', 'fb0f36b9-b77b-55d4-bae0-2d3f2779b6f4', 'transfer', 'Helicopter Along the Coast', 'Seven minutes from Monaco to Nice', 'Private charter from the Monaco Heliport, arranged around your plans.', 15, 190000, 'EUR', false, true, null, array['private', 'transport']::text[], '{"alt":"Helicopter over the coast","tone":["#1F3A4D","#7F9C96"]}'::jsonb, 'private', array['Private charter', 'Car to and from the heliport']::text[], 'Monte Carlo', 'waitlist', 'Requested. Awaiting the charter operator', 26)
