  ('d567712e-148e-55c1-9cda-458d8c76ed61', 'd1434b25-5668-5426-9bdd-6e47b5df109d', '541910dc-d171-542d-8575-3a8d893adf79', 'suite-ambassador', '2027-04-26T15:02:00-04:00')
insert into public.concierge_messages (id, conversation_id, author, author_name, body, intent, attachments, suggestions, created_at) values
  ('5cdb0fdf-8371-55c9-b043-e057607fb9df', 'd567712e-148e-55c1-9cda-458d8c76ed61', 'guest', null, 'Our 20th anniversary falls during the voyage. Could you arrange something special in Monaco?', null, '[]'::jsonb, '{}'::text[], '2027-04-26T15:02:00-04:00'),
  ('110b318e-ae06-58c7-9c52-5088034dd50f', 'd567712e-148e-55c1-9cda-458d8c76ed61', 'ai', null, 'Congratulations, Mr. Laurent. Your anniversary on 20 May falls on your second day in Monte Carlo. I’ve asked Elena, your Suite Ambassador, to plan it with you personally.', 'occasion.plan', '[]'::jsonb, '{}'::text[], '2027-04-26T15:02:20-04:00'),
  ('821f3813-e60e-576e-88fa-59777b4cd60c', 'd567712e-148e-55c1-9cda-458d8c76ed61', 'human', 'Elena, Suite Ambassador', 'Good afternoon, Alexander. I would love to help. A private terrace dinner, a menu with the chef, and a red from 2007, perhaps? I will keep it entirely between us.', null, '[]'::jsonb, '{}'::text[], '2027-04-26T15:18:00-04:00'),
  ('48c66b05-b812-5cfe-91ab-3dde3b04aa7d', 'd567712e-148e-55c1-9cda-458d8c76ed61', 'guest', null, 'Perfect. A Barolo if possible. And a couples spa that afternoon.', null, '[]'::jsonb, '{}'::text[], '2027-04-26T15:20:00-04:00'),
  ('61bc61c7-b25b-5916-8850-8f48437b2a2f', 'd567712e-148e-55c1-9cda-458d8c76ed61', 'human', 'Elena, Suite Ambassador', 'Done: the couples terrace ritual at 16:00 is reserved, and Luca, our head sommelier, is sourcing the Barolo. I will share the menu with you before you sail.', null, '[]'::jsonb, '{}'::text[], '2027-04-26T15:31:00-04:00')
